import{_ as a,o as s,c as i,a3 as t}from"./chunks/framework.B7pF4b99.js";const k=JSON.parse('{"title":"Spec 31：WUFS 非空白磁碟保護與固定驗證入口","description":"","frontmatter":{},"headers":[],"relativePath":"SPEC-31-filesystem-initialization-guard.md","filePath":"SPEC-31-filesystem-initialization-guard.md","lastUpdated":1794034236000}'),l={name:"SPEC-31-filesystem-initialization-guard.md"};function d(o,e,n,r,c,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="spec-31-wufs-非空白磁碟保護與固定驗證入口" tabindex="-1">Spec 31：WUFS 非空白磁碟保護與固定驗證入口 <a class="header-anchor" href="#spec-31-wufs-非空白磁碟保護與固定驗證入口" aria-label="Permalink to &quot;Spec 31：WUFS 非空白磁碟保護與固定驗證入口&quot;">​</a></h1><p>日期：2026-11-05。</p><p>狀態：程式碼與操作工具已實作；使用者於 2026-11-05 確認本項驗證完成。</p><h2 id="問題與目標" tabindex="-1">問題與目標 <a class="header-anchor" href="#問題與目標" aria-label="Permalink to &quot;問題與目標&quot;">​</a></h2><p>原本 kernel 的 <code>fs_init</code> 與主機的 <code>make_disk.py</code> 都會在 WUFS magic 不符時進入格式化。格式標記不符可能代表檔頭損毀或其他格式，不能作為清除既有資料的依據。</p><p>本階段將自動初始化限制為可確認空白的媒體。空白的定義是全部 bytes 皆為零，不包含全 <code>0xff</code> 或只有第一個磁區為零的映像。</p><h2 id="kernel-判斷流程" tabindex="-1">Kernel 判斷流程 <a class="header-anchor" href="#kernel-判斷流程" aria-label="Permalink to &quot;Kernel 判斷流程&quot;">​</a></h2><ol><li>初始化時清除掛載狀態，取得容量並讀取第一個磁區。</li><li>magic 為 <code>WUFS0001</code> 時，沿原有 superblock 欄位檢查與掛載流程處理。</li><li>magic 不符且容量回報為 <code>UINT32_MAX</code> 時，拒絕自動格式化。底層容量介面會飽和到這個值，不能據此保證已覆蓋完整裝置。</li><li>其他未知格式由 <code>disk_is_blank</code> 逐磁區只讀掃描：任何非零資料代表非空白；任何讀取錯誤代表無法判定。</li><li>僅完整掃描成功且全部為零，才能呼叫 formatter。格式化失敗時清除掛載狀態。</li></ol><p>掃描函式的回傳契約為 <code>1</code> 全零、<code>0</code> 發現資料、<code>-1</code> 讀取失敗。最壞時間 O(磁碟 bytes)，額外 kernel stack 空間 512 bytes。正常 WUFS 掛載不做全碟掃描。</p><p>這是開機期間的檢查，檢查與格式化之間不能有其他寫入者。工程註解記錄了此條件、回傳契約、完整掃描原因與容量截斷限制。</p><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/800a805/kernel/fs.c" target="_blank" rel="noreferrer">kernel/fs.c</a>。</p><h2 id="主機映像工具" tabindex="-1">主機映像工具 <a class="header-anchor" href="#主機映像工具" aria-label="Permalink to &quot;主機映像工具&quot;">​</a></h2><p>一般啟動會先經過 <code>make disk-image</code>，因此只修改 kernel 不足以保護映像。<code>tools/make_disk.py</code> 現在對既有映像採以下規則：</p><ul><li>magic 相符：依原有 WUFS 更新流程處理。</li><li>magic 不符但整個映像皆為零：可建立新 WUFS。</li><li>magic 不符且存在任何非零資料：以錯誤結束，不寫回映像。</li><li>映像不存在：可建立新的 WUFS 映像。</li></ul><p>主機工具沿用整個檔案讀入記憶體的實作；kernel 則使用單一磁區緩衝區。兩者都不能把已清零的檔頭當成整個映像為空白。</p><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/tools/make_disk.py" target="_blank" rel="noreferrer">tools/make_disk.py</a>。</p><h2 id="固定測試入口" tabindex="-1">固定測試入口 <a class="header-anchor" href="#固定測試入口" aria-label="Permalink to &quot;固定測試入口&quot;">​</a></h2><p>在含本次修正與 portable 工具環境的專案根目錄，使用 PowerShell 執行：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> valid</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> blank</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> damaged</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tail</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>這是專案內的 CMD 入口，不是需要先定義的 PowerShell 函式。每次執行會自動編譯 <code>all</code> 與 <code>build/kernel-disk.elf</code>，不需要另貼底層 Bash 或 Make 環境設定指令。</p><p>工具會在 <code>build/fs-check-案例-隨機名稱</code> 建立新的測試磁碟與 swap，直接交給 QEMU，不使用平常的 WUFS／swap 映像。它不經 <code>disk-image</code> target，以免主機預先格式化而測不到 kernel；也不使用 <code>-snapshot</code>，避免磁碟寫入被暫存 overlay 隱藏。</p><table tabindex="0"><thead><tr><th>案例</th><th>初始資料</th><th>預期 kernel 訊息</th><th>結束後磁碟</th></tr></thead><tbody><tr><td><code>valid</code></td><td>正常 WUFS</td><td><code>Mounted existing WUFS volume</code></td><td>SHA-256 不變</td></tr><tr><td><code>blank</code></td><td>16 MiB 全零</td><td><code>Initializing blank disk as WUFS</code></td><td>SHA-256 改變且開頭為 <code>WUFS0001</code></td></tr><tr><td><code>damaged</code></td><td>正常 WUFS 的第一個 512-byte 磁區被清零</td><td><code>Unknown or damaged filesystem on nonblank disk; refusing format</code></td><td>SHA-256 不變</td></tr><tr><td><code>tail</code></td><td>全零映像只在最後一個 byte 放 <code>0xa5</code></td><td>同上，拒絕格式化</td><td>SHA-256 不變</td></tr></tbody></table><p>請人工確認開機訊息，只執行 <code>help</code>／<code>ls</code> 等讀取操作。按 <strong>Ctrl+A</strong>，放開後按 <strong>X</strong> 結束 QEMU，工具才會比較前後雜湊並顯示 <code>PASS</code> 或 <code>FAIL</code>。非空白拒絕掛載案例仍應能進入 shell，檔案系統操作則可能返回未掛載錯誤。</p><p><code>PASS</code> 只代表工具所檢查的磁碟內容條件，不能替代掛載訊息及 shell 行為的人工確認。每次使用新磁碟，空白案例可重複執行；工具會保留測試檔案供檢查。</p><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/Test-FsDisk.cmd" target="_blank" rel="noreferrer">Test-FsDisk.cmd</a>、<a href="https://github.com/johnson931128/WUWAOS/blob/main/tools/test_fs_disk.py" target="_blank" rel="noreferrer">tools/test_fs_disk.py</a>。</p><h2 id="驗證狀態與限制" tabindex="-1">驗證狀態與限制 <a class="header-anchor" href="#驗證狀態與限制" aria-label="Permalink to &quot;驗證狀態與限制&quot;">​</a></h2><ul><li>使用者於 2026-11-05 確認本項驗證完成；實際執行由使用者負責，尚未留存逐案例終端輸出及雜湊值。本確認不延伸為下列故障注入或主機工具分支已通過的證據。</li><li>主機工具的拒絕覆寫分支需另用獨立非空白映像執行，確認錯誤退出且前後雜湊不變；四個 QEMU 案例不會代測該分支。</li><li>尚未完成讀取錯誤、容量飽和與格式化中途失敗的故障注入驗收。底層 I/O 逾時仍依原有停止核心策略處理。</li><li>不新增 journal、fsck、檔案救援或完整 superblock／inode 一致性檢查；已辨識的 WUFS 仍使用既有驗證範圍。</li><li>文件網站的建置與發布只驗證文件產物，不代表執行了核心或互動測試。</li><li>本次修正及固定測試入口在 portable v1 之後；既有 Release ZIP 不隨文件網站更新而改變。</li></ul>`,27)])])}const b=a(l,[["render",d]]);export{k as __pageData,b as default};
